// astro.config.mjs  (astro 7.3.1, @astrojs/node 11.1.5, sharp 0.35.4)
import { defineConfig } from 'astro/config';
import node from '@astrojs/node';

export default defineConfig({
  output: 'server',
  adapter: node({ mode: 'standalone' }),
  image: {
    // Still required: without it baseService.getURL() returns the raw lh3 URL (no optimisation, no proxy).
    domains: ['lh3.googleusercontent.com'],
    endpoint: {
      route: '/_image',                    // default, shown for clarity
      entrypoint: 'src/image-endpoint.ts', // honoured in dev AND build; adapters only fill it when undefined
    },
    service: {
      entrypoint: 'astro/assets/services/sharp',
      config: { limitInputPixels: 30_000_000 }, // sharp default is 268402689
    },
  },
});
// Netlify variant: adapter: netlify({ imageCDN: false }) — otherwise /_image is bypassed by /.netlify/images.
// Vercel variant: leave imageService at its default (false).

// src/image-endpoint.ts
import type { APIRoute } from 'astro';
import { GET as devGET } from 'astro/assets/endpoint/dev';   // refuses to run outside dev
import { GET as nodeGET } from 'astro/assets/endpoint/node'; // reads local assets from dist/, fetches remote
import { ALLOWED_WIDTHS, getAllowedImageHrefs } from './lib/catalogue-cache';

const delegate: APIRoute = import.meta.env.DEV ? devGET : nodeGET;

export const GET: APIRoute = async (ctx) => {
  const { searchParams } = new URL(ctx.request.url);
  const href = searchParams.get('href') ?? '';
  const w = searchParams.get('w');

  // Positive check for same-origin assets: exactly one leading slash (e.g. /_astro/logo.abc.png).
  // Anything else (https:, data:, //host/..) must be an href the catalogue itself emitted.
  const isSameOriginAsset = /^\/(?!\/)/.test(href);
  if (!isSameOriginAsset) {
    const allowed = await getAllowedImageHrefs(); // Set<string> from the TTL-cached sheet snapshot
    if (!allowed.has(href)) return new Response('Forbidden', { status: 403 });
    if (w !== null && !ALLOWED_WIDTHS.has(Number(w))) return new Response('Forbidden', { status: 403 });
  }
  // Built-in path: parseURL -> isRemoteAllowed -> fetchWithRedirects (no redirects, allow-list re-checked)
  //                -> sharp transform -> Cache-Control: public, max-age=31536000 + ETag
  return delegate(ctx);
};

// src/lib/catalogue-cache.ts (excerpt)
export const ALLOWED_WIDTHS = new Set([320, 640, 960, 1280, 1600]);

// Single source of truth for the URL string: used by <Image src=...> AND by the allow-list.
export function driveImageUrl(fileId: string, size = 1600): string {
  return `https://lh3.googleusercontent.com/d/${fileId}=s${size}`;
}

let allowlist: { snapshotId: number; set: Set<string> } | undefined;

export async function getAllowedImageHrefs(): Promise<Set<string>> {
  const snap = await getCatalogue(); // TTL cache; returns last-good snapshot if Sheets is down
  if (!allowlist || allowlist.snapshotId !== snap.loadedAt) {
    const set = new Set<string>();
    for (const rug of snap.rugs) for (const id of rug.imageIds) set.add(driveImageUrl(id));
    allowlist = { snapshotId: snap.loadedAt, set };
  }
  return allowlist.set;
}

