import { describe, expect, it, vi } from 'vitest';

vi.mock('astro/assets/endpoint/node', () => ({ GET: vi.fn(async () => new Response('ok', { status: 200 })) }));
vi.mock('astro/assets/endpoint/dev', () => ({ GET: vi.fn(async () => new Response('ok', { status: 200 })) }));
vi.mock('../src/lib/catalogue-cache', () => ({
  ALLOWED_WIDTHS: new Set([640]),
  getAllowedImageHrefs: async () => new Set(['https://lh3.googleusercontent.com/d/KNOWN=s1600']),
}));

import { GET } from '../src/image-endpoint';
const call = (qs: string) => GET({ request: new Request(`http://localhost/_image?${qs}`) } as any);

describe('/_image allow-list', () => {
  it('403 for a Drive id not in the sheet', async () => {
    expect((await call('href=https://lh3.googleusercontent.com/d/UNKNOWN=s1600&w=640')).status).toBe(403);
  });
  it('403 for an unlisted width', async () => {
    expect((await call('href=https://lh3.googleusercontent.com/d/KNOWN=s1600&w=641')).status).toBe(403);
  });
  it('403 for protocol-relative and data: hrefs', async () => {
    expect((await call('href=//evil.example/x.png&w=640')).status).toBe(403);
    expect((await call('href=data:image/svg%2Bxml,%3Csvg%3E&w=640')).status).toBe(403);
  });
  it('delegates for a known id and width', async () => {
    expect((await call('href=https://lh3.googleusercontent.com/d/KNOWN=s1600&w=640')).status).toBe(200);
  });
  it('delegates same-origin /_astro assets untouched', async () => {
    expect((await call('href=/_astro/logo.abc123.png&w=640')).status).toBe(200);
  });
});
